import React, { useState } from "react";
import { Box, Button, Divider, Grid2 as Grid, Paper, Typography, TextField, CircularProgress } from "@mui/material";
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { renderTimeViewClock } from '@mui/x-date-pickers/timeViewRenderers';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { useForm } from 'react-hook-form';
import moment from "moment";
import { UPLOAD_BULK_CSV_ROUTE, UPLOAD_FILE_ROUTE } from "../config/routeConfig";
import { getToken } from "../utils/GenUtils";
import { ToastContainer, toast } from "react-toastify";
import axios from "axios";
import { AdapterMoment } from "@mui/x-date-pickers/AdapterMoment";
import { useNavigate } from "react-router-dom";
import { MAX_FILE_SIZE_LIMIT } from "../constants/Constant";

export default function FileUploadPage() {
  // State management for the two scenarios
  const [file, setFile] = useState(null); // For general file upload
  const [urlName, setUrlName] = useState("");
  const [expirationDate, setExpirationDate] = useState(moment());
  const [csvFile, setCsvFile] = useState(null); // For CSV upload
  const [fileLoading, setFileLoading] = useState(false); // Loading state
  const [csvLoading, setCsvLoading] = useState(false); // Loading state
  const [shortUrl, setShortUrl] = useState(null); // Generated short URL
  const navigate = useNavigate();

  const { handleSubmit } = useForm();

  const fileUpload = (e) => {
    console.log("Event::");
    console.log(e.target.files[0]);
    setFile(e.target.files[0])
  }

  const handleChange = (e, error = '', type) => {
    console.log("Event");
    console.log(e, error = '', type);
    if (type && type === 'expirationDate') {
      // let value = e;
      // value = value ? new Date(value).toISOString() : new Date().toISOString()
      setExpirationDate(moment(e));
      // setError(prevState => {
      //   return { ...prevState, expirationDate: false, ED_helperText: "" }
      // })
    } else if (e.target.name === 'urlName') {
      setUrlName(e.target.value);
      // setError(prevState => {
      //   return { ...prevState, urlName: false, UN_helperText: "" }
      // })
    }
  }

  // Handle general file upload
  const handleFileUpload = async (e) => {
    e.preventDefault();
    setFileLoading(true);
    if (file.size >= MAX_FILE_SIZE_LIMIT) {
      toast("File size must not exceed 5 MB.", { autoClose: 1500 });
      setFileLoading(false);
      return;
    }
    const formData = new FormData();
    formData.append("file", file);
    formData.append("expirationDate", expirationDate);
    formData.append("urlName", urlName);
    axios({
      url: UPLOAD_FILE_ROUTE,
      method: "post",
      headers: {
        Authorization: getToken(),
      },
      data: formData
    })
    .then(res => {
      if (res.data && res.data.code === 200) {
        console.log("RES::UploadFile");
        console.log(res.data);
        let { data } = res;
        toast(data.message, { autoClose: 1500 });
        setShortUrl(data.data.url);
        setFileLoading(false);
        setFile(null);
        setUrlName("");
        setExpirationDate(null);
      }
    })
    .catch(err => {
      setFileLoading(false);
      console.log("Error::UploadFile");
      console.log(err);
      let {
        response: { data },
      } = err;
      if (data.status === 401) {
        navigate("/login")
      }
      let message = data?.error ? data.error[0].message : data.message;
      toast(message, { autoClose: 1500 });
    })
  };

  // Handle CSV file upload for URLs
  const handleCsvUpload = async (e) => {
    e.preventDefault();
    setCsvLoading(true);
    const formData = new FormData();
    formData.append("file", csvFile);
    axios({
      url: UPLOAD_BULK_CSV_ROUTE,
      method: "post",
      headers: {
        Authorization: getToken(),
      },
      data: formData
    })
    .then(res => {
      if (res.data && res.data.code === 200) {
        console.log("RES::BulkCsvFile");
        console.log(res.data);
        let { data } = res;
        toast(data.message, { autoClose: 1500 });
        // setShortUrl(data.data.url);
        setCsvLoading(false);
        setCsvFile(null);
      }
    })
    .catch(err => {
      setCsvLoading(false);
      console.log("Error::BulkCsvFile");
      console.log(err);
      let {
        response: { data },
      } = err;
      if (data.status === 401) {
        navigate("/login")
      }
      let message = data?.error ? data.error[0].message : data.message;
      toast(message, { autoClose: 1500 });
    })
  };

  // Handle going back
  const handleBack = () => {
    navigate("/"); // Go back to the previous page
  };

  return (
    <Box sx={{ maxWidth: 800, margin: "auto", mt: 4 }}>
      <ToastContainer />
      <Paper elevation={3} sx={{ p: 4 }}>
        {/* Back Button */}
        <Button variant="outlined" startIcon={<ArrowBackIcon />} onClick={handleBack} sx={{ mb: 2 }}>
          Back
        </Button>
        <Typography variant="h4" gutterBottom>
          File Upload Dashboard
        </Typography>

        {/* Section 1: General File Upload */}
        <Box component="form" onSubmit={handleFileUpload}>
          <Typography variant="h6">Upload Any File (PDF, Image, Video)</Typography>
          <TextField
            fullWidth
            type="file"
            slotProps={{
                htmlInput: {
                    accept: "image/*,application/pdf,video/*",
                  }
            }}
            // onChange={fileUpload}
            onChange={(e) => setFile(e.target.files[0])}
            sx={{ mt: 2 }}
          />
          <TextField
            fullWidth
            label="URL Name"
            name="urlName"
            value={urlName}
            onChange={handleChange}
            required
            sx={{ mt: 2 }}
            slotProps={{ htmlInput: { "aria-label": "urlName" } }}
          />
          <LocalizationProvider dateAdapter={AdapterMoment}>
            <DateTimePicker
              label="Expiration Date"
              name="expirationDate"
              format="DD/MM/YYYY hh:mm a"
              showDaysOutsideCurrentMonth={true}
              value={expirationDate}
              sx={{ mt: 2 }}
              slotProps={{
                textField: {
                  fullWidth: true,
                  margin: "normal",
                  // error: error.expirationDate,
                  // helperText: error.ED_helperText
                },
                // field: { clearable: true },
                actionBar: {
                  actions: ["cancel"],
                },
              }}
              onChange={(value, error) =>
                handleChange(value, error, "expirationDate")
              }
              viewRenderers={{
                hours: renderTimeViewClock,
                minutes: renderTimeViewClock,
                seconds: renderTimeViewClock,
              }}
            />
          </LocalizationProvider>
          <Button
            type="submit"
            variant="contained"
            color="primary"
            startIcon={<CloudUploadIcon />}
            disabled={fileLoading || !file}
            sx={{ mt: 2 }}
          >
            {fileLoading ? <CircularProgress size={24} /> : "Upload File"}
          </Button>
          {shortUrl && (
            <Typography variant="body1" sx={{ mt: 2 }}>
              Short URL: <a href={shortUrl} target="_blank" rel="noopener noreferrer">{shortUrl}</a>
            </Typography>
          )}
        </Box>

        {/* Divider between the two sections */}
        <Divider sx={{ my: 4 }} />

        {/* Section 2: CSV Upload for URLs */}
        <Box component="form" onSubmit={handleCsvUpload}>
          <Typography variant="h6">Upload CSV File with URLs</Typography>
          <TextField
            fullWidth
            type="file"
            slotProps={{
                htmlInput: {
                    accept: ".csv"
                }
            }}
            onChange={(e) => setCsvFile(e.target.files[0])}
            sx={{ mt: 2, mb: 2 }}
          />
          <Button
            type="submit"
            variant="contained"
            color="primary"
            startIcon={<CloudUploadIcon />}
            disabled={csvLoading || !csvFile}
          >
            {csvLoading ? <CircularProgress size={24} /> : "Upload CSV"}
          </Button>
        </Box>
      </Paper>
    </Box>
  );
}
