import * as React from "react";
import CheckRoundedIcon from '@mui/icons-material/CheckRounded';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import Button from "@mui/material/Button";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import DialogContentText from "@mui/material/DialogContentText";
import DialogTitle from "@mui/material/DialogTitle";
import useMediaQuery from "@mui/material/useMediaQuery";
import { useTheme } from "@mui/material/styles";
import { QRCodeSVG } from 'qrcode.react';
import { CircularProgress } from "@mui/material";

export default function AlertBox(props) {
  const theme = useTheme();
  // const isDarkMode = theme.palette.mode === "dark";
  // let qrCodeBgColor = '#FFFFFF', qrCodeFgColor = '#000000';
  // if (isDarkMode) {
  //   qrCodeBgColor = '#000000';
  //   qrCodeFgColor = '#FFFFFF';
  // }
  const fullScreen = useMediaQuery(theme.breakpoints.down("sm"));
  const isMedium = useMediaQuery(theme.breakpoints.between("sm", "md"));
  const isLarge = useMediaQuery(theme.breakpoints.up("md"));
  
  const {
    open,
    handleClose,
    handleConfirm,
    modalContent = "Short URL Information", // Default content
    // qrValue = "http://localhost:4000", // Default QR value if none is passed
    loading = false,
  } = props;

  return (
    <React.Fragment>
      <Dialog
        open={open}
        onClose={handleClose}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
        fullScreen={fullScreen}
        fullWidth={true}
        maxWidth={fullScreen ? "xs" : isMedium ? "sm" : isLarge ? "md" : "lg"}
      >
        <DialogTitle id="alert-dialog-title">
          {"Short URL Details"}
        </DialogTitle>
        <DialogContent dividers={true}>
          <DialogContentText id="alert-dialog-description">
            {modalContent}
          </DialogContentText>
          {/* <div style={{ display: 'flex', justifyContent: 'normal', marginTop: '20px' }}>
            <QRCodeSVG value={qrValue} size={120} bgColor={qrCodeBgColor} fgColor={qrCodeFgColor} />
          </div> */}
        </DialogContent>
        <DialogActions>
          <Button
            variant="outlined"
            onClick={handleClose}
            startIcon={<CloseRoundedIcon />}
          >
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={handleConfirm}
            disabled={loading}
            startIcon={<CheckRoundedIcon />}
          >
            
            {loading ? <CircularProgress size={24} /> : 'Confirm'}
          </Button>
        </DialogActions>
      </Dialog>
    </React.Fragment>
  );
}
